    local function executeProto(proto, env, upvalues, varargs)
        local registers = {}
        -- Self-Erasing: each invocation gets its own code snapshot so that
        -- recursive calls and sibling closures always see the original bytecode.
        local code      = {}
        for _ci = 1, #proto.code do code[_ci] = proto.code[_ci] end
        local kst       = {}
        for _ki = 1, #proto.constants do kst[_ki] = proto.constants[_ki] end
        local subProtos = proto.subProtos
        local pc        = 1
        varargs         = varargs or {}

        -- Circular Shifting Registers (Tier 5 Anti-SSA Protection)
        -- Dynamic per-proto base offset derived from proto characteristics.
        -- Every prototype gets a different base register offset (e.g. 19, 56, 127...)
        -- making static Single Static Assignment (SSA) recovery impossible.
        local _reg_base = ((proto.numParams * 37 + #proto.code * 13 + #proto.constants * 7 + 19) % 239) + 1
        local _cur_seed = _reg_base

        local var_map = proto.varMap or {}

        -- Register access with Circular Shift applied
        -- Uses _cur_seed (snapshot for current instruction) not the live seed.
        local function REG(slot)
            return registers[(slot + _cur_seed) % _MAX_STACK]
        end
        local function SETREG(slot, val)
            registers[(slot + _cur_seed) % _MAX_STACK] = val
        end

        -- Lexical upvalue scope linking for circular shifting registers
        local upval_scope = setmetatable({}, {
            __index = function(_, id)
                local slot = var_map[id]
                if slot ~= nil then
                    return REG(slot)
                end
                if upvalues then
                    return upvalues[id]
                end
                return nil
            end,
            __newindex = function(_, id, val)
                local slot = var_map[id]
                if slot ~= nil then
                    SETREG(slot, val)
                elseif upvalues then
                    upvalues[id] = val
                end
            end
        })

        -- Load parameters into shifted slots
        for i = 1, proto.numParams do
            local shifted = (i - 1 + _reg_base) % _MAX_STACK
            registers[shifted] = varargs[i]
        end

        local function getK(idx)
            local item = kst[idx]
            if type(item) == "table" and item[1] == 1337 then
                local key     = item[2]
                local encData = item[3]
                local slen    = #encData
                local bytes   = {}
                for s = 1, slen do
                    local b    = _byte(encData, s)
                    local orig = _bxor(_bxor(b, key), ((s - 1) * 7 + 13) % 256)
                    bytes[s]   = _char(orig)
                end
                local decrypted = table.concat(bytes)
                kst[idx]        = decrypted
                return decrypted
            end
            return item
        end

        local function RK(idx)
            if idx >= 256 then
                return getK(idx - 255)
            end
            return REG(idx)
        end

        -- Tier-5 Safe Self-Erasing Bytecode (Memory Dump Protection)
        -- Pre-calculate all loop spans (from backward jump target to source).
        -- Instructions within loops survive for subsequent iterations.
        -- All instructions outside loops are nil'd immediately upon execution.
        local _in_loop = {}
        for _li = 1, #code do
            local _inst = code[_li]
            if _inst and _inst.sbx and _inst.sbx < 0 then
                local _target = _li + 1 + _inst.sbx
                if _target < _li then
                    for _k = _target, _li do
                        _in_loop[_k] = true
                    end
                end
            end
        end

        local _running = true
        local _retvals = nil

        while _running do
            local inst = code[pc]
            if not inst then _running = false; break end
            local _cur_pc = pc
            pc = pc + 1

            -- Self-erasing: wipe bytecode slot in memory immediately if not in loop
            if not _in_loop[_cur_pc] then
                code[_cur_pc] = nil
            end

            local op = inst.op

            -- Control Flow Flattened Binary Search Dispatcher
            if op < 131 then
              if op < 68 then
                if op < 29 then
                  if op < 14 then
                    if op < 9 then
                      if op == 1 then
                        -- Opcode: NOT (1)
                        SETREG(inst.a, not REG(inst.b))
                      else
                        -- Opcode: DIV (4)
                        SETREG(inst.a, RK(inst.b) / RK(inst.c))
                      end
                    else
                      if op == 9 then
                        -- Opcode: TESTSET (9)
                        local _b = REG(inst.b)
                        if (not _b) ~= (inst.c == 0) then
                            pc = pc + 1
                        else
                            SETREG(inst.a, _b)
                        end
                      else
                        -- Opcode: LT (10)
                        local _b = RK(inst.b)
                        local _c = RK(inst.c)
                        if (_b < _c) ~= (inst.a ~= 0) then
                            pc = pc + 1
                        end
                      end
                    end
                  else
                    if op < 17 then
                      if op == 14 then
                        -- Opcode: GETGLOBAL (14)
                        local _k = getK(inst.b + 1)
                        SETREG(inst.a, env[_k])
                      else
                        -- Opcode: DIV (15)
                        SETREG(inst.a, RK(inst.b) / RK(inst.c))
                      end
                    else
                      if op < 25 then
                        -- Opcode: MOD (17)
                        SETREG(inst.a, RK(inst.b) % RK(inst.c))
                      else
                        if op == 25 then
                          -- Opcode: LOADBOOL (25)
                          SETREG(inst.a, (inst.b ~= 0))
                          if inst.c ~= 0 then pc = pc + 1 end
                        else
                          -- Opcode: ADD (28)
                          SETREG(inst.a, RK(inst.b) + RK(inst.c))
                        end
                      end
                    end
                  end
                else
                  if op < 46 then
                    if op < 39 then
                      if op == 29 then
                        -- Opcode: FORLOOP (29)
                        local _step   = REG(inst.a + 2)
                        local _limit  = REG(inst.a + 1)
                        local _nextV  = REG(inst.a) + _step
                        SETREG(inst.a, _nextV)
                        SETREG(inst.a + 3, _nextV)
                        if (_step > 0 and _nextV <= _limit) or (_step <= 0 and _nextV >= _limit) then
                            pc = pc + inst.sbx
                        end
                      else
                        -- Opcode: POW (33)
                        SETREG(inst.a, RK(inst.b) ^ RK(inst.c))
                      end
                    else
                      if op == 39 then
                        -- Opcode: LE (39)
                        local _b = RK(inst.b)
                        local _c = RK(inst.c)
                        if (_b <= _c) ~= (inst.a ~= 0) then
                            pc = pc + 1
                        end
                      else
                        -- Opcode: SUB (43)
                        SETREG(inst.a, RK(inst.b) - RK(inst.c))
                      end
                    end
                  else
                    if op < 60 then
                      if op == 46 then
                        -- Opcode: VARARG (46)
                        local _n = inst.b - 1
                        for _i = 1, _n do
                            SETREG(inst.a + _i - 1, varargs[_i])
                        end
                      else
                        -- Opcode: ADD (59)
                        SETREG(inst.a, RK(inst.b) + RK(inst.c))
                      end
                    else
                      if op < 64 then
                        -- Opcode: SELF (60)
                        local _obj = REG(inst.b)
                        SETREG(inst.a + 1, _obj)
                        SETREG(inst.a, _obj[RK(inst.c)])
                      else
                        if op == 64 then
                          -- Opcode: LOADNIL (64)
                          for _i = inst.a, inst.b do SETREG(_i, nil) end
                        else
                          -- Opcode: CLOSURE (67)
                          local _subP = subProtos[inst.b + 1]
                          SETREG(inst.a, function(...)
                              return executeProto(_subP, env, upval_scope, {...})
                          end)
                        end
                      end
                    end
                  end
                end
              else
                if op < 95 then
                  if op < 84 then
                    if op < 80 then
                      if op == 68 then
                        -- Opcode: MOVE (68)
                        SETREG(inst.a, REG(inst.b))
                      else
                        -- Opcode: LOADK (77)
                        SETREG(inst.a, getK(inst.b + 1))
                      end
                    else
                      if op == 80 then
                        -- Opcode: MUL (80)
                        SETREG(inst.a, RK(inst.b) * RK(inst.c))
                      else
                        -- Opcode: GETUPVAL (82)
                        SETREG(inst.a, upval_scope[inst.b])
                      end
                    end
                  else
                    if op < 86 then
                      if op == 84 then
                        -- Opcode: UNM (84)
                        SETREG(inst.a, -REG(inst.b))
                      else
                        -- Opcode: MOVE (85)
                        SETREG(inst.a, REG(inst.b))
                      end
                    else
                      if op < 90 then
                        -- Opcode: SUB (86)
                        SETREG(inst.a, RK(inst.b) - RK(inst.c))
                      else
                        if op == 90 then
                          -- Opcode: TESTSET (90)
                          local _b = REG(inst.b)
                          if (not _b) ~= (inst.c == 0) then
                              pc = pc + 1
                          else
                              SETREG(inst.a, _b)
                          end
                        else
                          -- Opcode: RETURN (92)
                          local _nRet = inst.b - 1
                          if _nRet == 0 then
                              _running = false
                          elseif _nRet == 1 then
                              _retvals = { REG(inst.a) }
                              _running = false
                          else
                              _retvals = {}
                              for _i = 1, _nRet do
                                  _retvals[_i] = REG(inst.a + _i - 1)
                              end
                              _running = false
                          end
                        end
                      end
                    end
                  end
                else
                  if op < 119 then
                    if op < 105 then
                      if op == 95 then
                        -- Opcode: MOD (95)
                        SETREG(inst.a, RK(inst.b) % RK(inst.c))
                      else
                        -- Opcode: JMP (97)
                        pc = pc + inst.sbx
                      end
                    else
                      if op == 105 then
                        -- Opcode: SETGLOBAL (105)
                        local _k = getK(inst.b + 1)
                        env[_k] = REG(inst.a)
                      else
                        -- Opcode: LEN (107)
                        SETREG(inst.a, #REG(inst.b))
                      end
                    end
                  else
                    if op < 121 then
                      if op == 119 then
                        -- Opcode: UNM (119)
                        SETREG(inst.a, -REG(inst.b))
                      else
                        -- Opcode: CLOSURE (120)
                        local _subP = subProtos[inst.b + 1]
                        SETREG(inst.a, function(...)
                            return executeProto(_subP, env, upval_scope, {...})
                        end)
                      end
                    else
                      if op < 123 then
                        -- Opcode: LT (121)
                        local _b = RK(inst.b)
                        local _c = RK(inst.c)
                        if (_b < _c) ~= (inst.a ~= 0) then
                            pc = pc + 1
                        end
                      else
                        if op == 123 then
                          -- Opcode: EQ (123)
                          local _b = RK(inst.b)
                          local _c = RK(inst.c)
                          if (_b == _c) ~= (inst.a ~= 0) then
                              pc = pc + 1
                          end
                        else
                          -- Opcode: TEST (126)
                          local _a = REG(inst.a)
                          if not (not _a == (inst.c == 0)) then
                              pc = pc + 1
                          end
                        end
                      end
                    end
                  end
                end
              end
            else
              if op < 183 then
                if op < 152 then
                  if op < 140 then
                    if op < 135 then
                      if op == 131 then
                        -- Opcode: CONCAT (131)
                        SETREG(inst.a, RK(inst.b) .. RK(inst.c))
                      else
                        -- Opcode: SETUPVAL (132)
                        upval_scope[inst.b] = REG(inst.a)
                      end
                    else
                      if op == 135 then
                        -- Opcode: CLOSE (135)
                        -- close upvalues (no-op in pure Lua upvalue model)
                      else
                        -- Opcode: EQ (137)
                        local _b = RK(inst.b)
                        local _c = RK(inst.c)
                        if (_b == _c) ~= (inst.a ~= 0) then
                            pc = pc + 1
                        end
                      end
                    end
                  else
                    if op < 144 then
                      if op == 140 then
                        -- Opcode: LOADBOOL (140)
                        SETREG(inst.a, (inst.b ~= 0))
                        if inst.c ~= 0 then pc = pc + 1 end
                      else
                        -- Opcode: CALL (141)
                        local _f    = REG(inst.a)
                        local _args = {}
                        local _nA   = inst.b - 1
                        if _nA > 0 then
                            for _i = 1, _nA do
                                _args[_i] = REG(inst.a + _i)
                            end
                        end
                        local _res = { _f(_unpack(_args, 1, _nA > 0 and _nA or 0)) }
                        local _nR = inst.c - 1
                        if _nR > 0 then
                            for _i = 1, _nR do
                                SETREG(inst.a + _i - 1, _res[_i])
                            end
                        end
                      end
                    else
                      if op < 146 then
                        -- Opcode: TEST (144)
                        local _a = REG(inst.a)
                        if not (not _a == (inst.c == 0)) then
                            pc = pc + 1
                        end
                      else
                        if op == 146 then
                          -- Opcode: TFORLOOP (146)
                          local _f   = REG(inst.a)
                          local _s   = REG(inst.a + 1)
                          local _var = REG(inst.a + 2)
                          local _res = { _f(_s, _var) }
                          local _nR  = inst.c
                          for _i = 1, _nR do
                              SETREG(inst.a + 2 + _i, _res[_i])
                          end
                          if _res[1] ~= nil then
                              SETREG(inst.a + 2, _res[1])
                          else
                              pc = pc + 1
                          end
                        else
                          -- Opcode: GETTABLE (147)
                          local _tbl = REG(inst.b)
                          local _key = RK(inst.c)
                          SETREG(inst.a, _tbl[_key])
                        end
                      end
                    end
                  end
                else
                  if op < 165 then
                    if op < 157 then
                      if op == 152 then
                        -- Opcode: RETURN (152)
                        local _nRet = inst.b - 1
                        if _nRet == 0 then
                            _running = false
                        elseif _nRet == 1 then
                            _retvals = { REG(inst.a) }
                            _running = false
                        else
                            _retvals = {}
                            for _i = 1, _nRet do
                                _retvals[_i] = REG(inst.a + _i - 1)
                            end
                            _running = false
                        end
                      else
                        -- Opcode: CLOSE (156)
                        -- close upvalues (no-op in pure Lua upvalue model)
                      end
                    else
                      if op == 157 then
                        -- Opcode: SETTABLE (157)
                        local _tbl = REG(inst.a)
                        local _key = RK(inst.b)
                        local _val = RK(inst.c)
                        _tbl[_key] = _val
                      else
                        -- Opcode: SELF (163)
                        local _obj = REG(inst.b)
                        SETREG(inst.a + 1, _obj)
                        SETREG(inst.a, _obj[RK(inst.c)])
                      end
                    end
                  else
                    if op < 172 then
                      if op == 165 then
                        -- Opcode: NEWTABLE (165)
                        SETREG(inst.a, {})
                      else
                        -- Opcode: FORLOOP (168)
                        local _step   = REG(inst.a + 2)
                        local _limit  = REG(inst.a + 1)
                        local _nextV  = REG(inst.a) + _step
                        SETREG(inst.a, _nextV)
                        SETREG(inst.a + 3, _nextV)
                        if (_step > 0 and _nextV <= _limit) or (_step <= 0 and _nextV >= _limit) then
                            pc = pc + inst.sbx
                        end
                      end
                    else
                      if op < 173 then
                        -- Opcode: LE (172)
                        local _b = RK(inst.b)
                        local _c = RK(inst.c)
                        if (_b <= _c) ~= (inst.a ~= 0) then
                            pc = pc + 1
                        end
                      else
                        if op == 173 then
                          -- Opcode: GETGLOBAL (173)
                          local _k = getK(inst.b + 1)
                          SETREG(inst.a, env[_k])
                        else
                          -- Opcode: MUL (182)
                          SETREG(inst.a, RK(inst.b) * RK(inst.c))
                        end
                      end
                    end
                  end
                end
              else
                if op < 232 then
                  if op < 211 then
                    if op < 196 then
                      if op == 183 then
                        -- Opcode: LEN (183)
                        SETREG(inst.a, #REG(inst.b))
                      else
                        -- Opcode: NEWTABLE (192)
                        SETREG(inst.a, {})
                      end
                    else
                      if op == 196 then
                        -- Opcode: SETGLOBAL (196)
                        local _k = getK(inst.b + 1)
                        env[_k] = REG(inst.a)
                      else
                        -- Opcode: FORPREP (204)
                        local _init  = REG(inst.a)
                        local _limit = REG(inst.a + 1)
                        local _step  = REG(inst.a + 2)
                        SETREG(inst.a + 3, _init)
                        if (_step > 0 and _init > _limit) or (_step <= 0 and _init < _limit) then
                            pc = pc + inst.sbx
                        end
                      end
                    end
                  else
                    if op < 225 then
                      if op == 211 then
                        -- Opcode: CONCAT (211)
                        SETREG(inst.a, RK(inst.b) .. RK(inst.c))
                      else
                        -- Opcode: VARARG (212)
                        local _n = inst.b - 1
                        for _i = 1, _n do
                            SETREG(inst.a + _i - 1, varargs[_i])
                        end
                      end
                    else
                      if op < 226 then
                        -- Opcode: GETTABLE (225)
                        local _tbl = REG(inst.b)
                        local _key = RK(inst.c)
                        SETREG(inst.a, _tbl[_key])
                      else
                        if op == 226 then
                          -- Opcode: LOADNIL (226)
                          for _i = inst.a, inst.b do SETREG(_i, nil) end
                        else
                          -- Opcode: CALL (231)
                          local _f    = REG(inst.a)
                          local _args = {}
                          local _nA   = inst.b - 1
                          if _nA > 0 then
                              for _i = 1, _nA do
                                  _args[_i] = REG(inst.a + _i)
                              end
                          end
                          local _res = { _f(_unpack(_args, 1, _nA > 0 and _nA or 0)) }
                          local _nR = inst.c - 1
                          if _nR > 0 then
                              for _i = 1, _nR do
                                  SETREG(inst.a + _i - 1, _res[_i])
                              end
                          end
                        end
                      end
                    end
                  end
                else
                  if op < 239 then
                    if op < 237 then
                      if op == 232 then
                        -- Opcode: LOADK (232)
                        SETREG(inst.a, getK(inst.b + 1))
                      else
                        -- Opcode: POW (233)
                        SETREG(inst.a, RK(inst.b) ^ RK(inst.c))
                      end
                    else
                      if op == 237 then
                        -- Opcode: SETUPVAL (237)
                        upval_scope[inst.b] = REG(inst.a)
                      else
                        -- Opcode: NOT (238)
                        SETREG(inst.a, not REG(inst.b))
                      end
                    end
                  else
                    if op < 247 then
                      if op == 239 then
                        -- Opcode: JMP (239)
                        pc = pc + inst.sbx
                      else
                        -- Opcode: TFORLOOP (241)
                        local _f   = REG(inst.a)
                        local _s   = REG(inst.a + 1)
                        local _var = REG(inst.a + 2)
                        local _res = { _f(_s, _var) }
                        local _nR  = inst.c
                        for _i = 1, _nR do
                            SETREG(inst.a + 2 + _i, _res[_i])
                        end
                        if _res[1] ~= nil then
                            SETREG(inst.a + 2, _res[1])
                        else
                            pc = pc + 1
                        end
                      end
                    else
                      if op < 253 then
                        -- Opcode: GETUPVAL (247)
                        SETREG(inst.a, upval_scope[inst.b])
                      else
                        if op == 253 then
                          -- Opcode: SETTABLE (253)
                          local _tbl = REG(inst.a)
                          local _key = RK(inst.b)
                          local _val = RK(inst.c)
                          _tbl[_key] = _val
                        else
                          -- Opcode: FORPREP (255)
                          local _init  = REG(inst.a)
                          local _limit = REG(inst.a + 1)
                          local _step  = REG(inst.a + 2)
                          SETREG(inst.a + 3, _init)
                          if (_step > 0 and _init > _limit) or (_step <= 0 and _init < _limit) then
                              pc = pc + inst.sbx
                          end
                        end
                      end
                    end
                  end
                end
              end
            end

        end

        -- Wipe any remaining bytecode from memory once proto finishes
        for _ci = 1, #code do code[_ci] = nil end

        if _retvals then
            return _unpack(_retvals, 1, #_retvals)
        end
    end

    local globalEnv = getfenv and getfenv() or _G
    return executeProto(mainProto, globalEnv, {}, {...})
end)(...)
